#include <iostream>
using namespace std;

int main() {
    cout << "Check which number? ";
    int n;
    cin >> n;

    bool found = false;

    for (int i = 2; i < n; i++) {
        if (n % i == 0) {
            cout << n << " divides by " << i << endl;
            found = true;
            break;
        }
    }

    if (!found) {
        cout << n << " is prime." << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int total = 0;

    while (true) {
        cout << "Amount (0 to finish)? ";
        int amount;
        cin >> amount;

        if (amount == 0) {
            break;                  // the only way out
        }

        if (amount < 0) {
            cout << "Ignoring " << amount << endl;
            continue;               // back to the top, nothing added
        }

        total += amount;
    }

    cout << "Total: " << total << endl;
    return 0;
}

