using namespace std;

int main() {
    for (int row = 1; row <= 3; row++) {
        for (int col = 1; col <= 5; col++) {
            if (col == 3) {
                break;              // leaves the col loop only
            }

            cout << col << " ";
        }

        cout << "<- end of row " << row << endl;
    }

    cout << "All rows done." << endl;
    return 0;
}

